+    let active = ReceiveDescriptor{coalescing: u8(22), class_tag: u8(119)};
+    let standby = ReceiveDescriptor{coalescing: u8(81), class_tag: u8(147)};
+    let rank = usize(11);
+    let blocks = if (rank < usize(8)) { usize(63) } else { usize(64) };
