+    let active_mode = active@coalescing;
+    let active_tag = active@class_tag;
+    let standby_mode = standby@coalescing;
+    let standby_tag = standby@class_tag;
+    let first_previous = old_active;
+    let second_previous = old_standby;
+    return unit;
+}

